The exam office removes every result below 50 points with the loop ported from C. What does this program print?

std::vector<int> points = {45, 30, 75, 20, 15, 90};
for (std::size_t i = 0; i < points.size(); ++i)
    if (points[i] < 50)
        points.erase(points.begin() + i);
for (int p : points) std::print("{} ", p);

